self.KB_CONTENT["card:758566"]={"id":"card:758566","ty":"card","sourceId":"758566","title":"『付款條件建立作業』的作業目的為何？","ver":"iGP","topic":"應付憑單","keywords":["應付憑單","進貨","採購","廠商"],"y":"explain","answer":"將廠商付款條件加以分類，依不同付款條件賦予代號，以便後續採購、進貨及應付憑單之篩選，若是廠商採固定的的付款方式，也可於廠商基本資料設定。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
