self.KB_CONTENT["card:755103"]={"id":"card:755103","ty":"card","sourceId":"755103","title":"『合約訂單建立作業』中的『送貨地址(一) (TW029)』為何？","ver":"iGP","topic":"客戶","keywords":["客戶","訂單","合約","地址"],"y":"other","answer":"* 可空白。* 可點選(icon)或[F2]客戶地址代號查詢，預設送貨地址(一)、送貨地址(二)、送貨客戶全名、連絡人、TEL_NO、FAX_NO。* [F3]地址資料查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
