self.KB_CONTENT["card:784826"]={"id":"card:784826","ty":"card","sourceId":"784826","title":"『資產減損憑證』中的『選擇單號 (TC002)』為何？","ver":"GP4以上","topic":"憑證","keywords":["憑證","資產","單號","折舊"],"y":"other","answer":"* 可輸入需列印資產折舊之單號範圍。若空白表全部單號皆納入。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
