self.KB_CONTENT["card:757538"]={"id":"card:757538","ty":"card","sourceId":"757538","title":"『每月發票建立作業』中的『申報公司 (MB001)』為何？","ver":"iGP","topic":"發票","keywords":["發票","開窗","每月","申報"],"y":"other","answer":"資料須先於「基本資料管理系統\\建立作業\\稅籍資料建立作業」建好才可在此按[F2]開窗找到申報公司的資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
