self.KB_CONTENT["card:754377"]={"id":"card:754377","ty":"card","sourceId":"754377","title":"『人才來源建立作業』的作業重點有哪些？","ver":"iGP","topic":"記錄","keywords":["記錄"],"y":"explain","answer":"1.可將各種人才來源，如：平面廣告、媒體廣告、人力網站、親友介紹、政府就業輔導、校園徵才…等資料輸入，後續就可在新增「人才庫」資料時，記錄該人員應徵工作的來源管道。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
