self.KB_CONTENT["field:780668"]={"id":"field:780668","ty":"field","sourceId":"780668","title":"選擇供應廠商","ver":"GP4以上","topic":"","keywords":[],"job":"IPSR14 SHIPPING INSTRUCTION","code":"TE003","answer":"* 可點選(icon)或[F2]廠商資料查詢需列印之供應廠商之範圍。其資料需存在於廠商資料檔內，若空白表全部。進階選項","file":"fields.jsonl"};
