self.KB_CONTENT["field:791411"]={"id":"field:791411","ty":"field","sourceId":"791411","title":"客戶商品描述空白依公司商品描述列印","ver":"GP4以上","topic":"","keywords":[],"job":"PROFORMA INVOICE","code":"","answer":"* 預設N。* 當選擇商品描述列印採「2.客戶商品描述」時，則此欄位才可輸入；否則預設為N且不可輸入。","file":"fields.jsonl"};
